import{_ as t,I as a,g as r,j as o}from"./chunks/framework.CjoWWfVe.js";const g=JSON.parse('{"title":"Ambassador Module","description":"Promotion, smart link generation, receipt QR codes, campaign CRM, and AI marketing assistant.","frontmatter":{"title":"Ambassador Module","description":"Promotion, smart link generation, receipt QR codes, campaign CRM, and AI marketing assistant.","order":17},"headers":[],"relativePath":"docs/spaces/ambassador.md","filePath":"docs/spaces/ambassador.md"}'),n={name:"docs/spaces/ambassador.md"};function i(s,e,l,c,d,m){return a(),r("div",null,[...e[0]||(e[0]=[o('<div class="warning custom-block"><p class="custom-block-title">📌 Documentation is under development</p><p><strong>Dear users!</strong></p><p>Since OmniCraft ERP is currently in an active beta stage, being regularly improved and expanded, the reference materials are also updated gradually.</p><p>At the moment, please treat the documentation as indicative — it is incomplete, may temporarily lack descriptions of some features, or contain inaccuracies.</p></div><h1 id="🚀-ambassador-module-marketing-partnership" tabindex="-1">🚀 Ambassador Module (Marketing &amp; Partnership) <a class="header-anchor" href="#🚀-ambassador-module-marketing-partnership" aria-label="Permalink to &quot;🚀 Ambassador Module (Marketing &amp; Partnership)&quot;">​</a></h1><p><strong>Ambassador</strong> is a free system tool designed to solve two key tasks for craftsmen and entrepreneurs:</p><ol><li><strong>Affiliate Income in the OmniCraft ERP Ecosystem:</strong> Recommend the software to colleagues, earn lifetime commission, and pay for subscriptions with accumulated points.</li><li><strong>Promoting Your Own Business:</strong> Smart link builder, campaign CRM tracker, and built-in AI assistant to promote your own handmade items, digital leather patterns, courses, or external software.</li></ol><hr><h2 id="🏗️-1-constructor-tab-smart-links-qr-code-generation" tabindex="-1">🏗️ 1. &quot;Constructor&quot; Tab: Smart Links &amp; QR Code Generation <a class="header-anchor" href="#🏗️-1-constructor-tab-smart-links-qr-code-generation" aria-label="Permalink to &quot;🏗️ 1. &quot;Constructor&quot; Tab: Smart Links &amp; QR Code Generation&quot;">​</a></h2><p>In the Constructor tab, you can prepare a custom link for any advertising post, article, or offline event in just a few clicks:</p><ul><li><strong>Link Destination:</strong><ul><li><em>OmniCraft ERP Affiliate:</em> Generates a link with your unique referral code (e.g., <code>INV-XXXX-XXXX</code>).</li><li><em>My Product / External Website:</em> Enter your own website, online store, or social group URL and automatically attach UTM tracking tags.</li></ul></li><li><strong>Traffic Source:</strong> Telegram, VKontakte, Habr / VC.ru, Pikabu, Livemaster, Offline / Craft Fairs, or Custom Channel.</li><li><strong>Instant QR Generation:</strong> The system immediately outputs the URL and a <strong>QR code</strong> ready for download and printing on business cards, price tags, or packaging.</li></ul><h3 id="🧾-offline-marketing-watermark-on-electronic-receipts" tabindex="-1">🧾 Offline Marketing: Watermark on Electronic Receipts <a class="header-anchor" href="#🧾-offline-marketing-watermark-on-electronic-receipts" aria-label="Permalink to &quot;🧾 Offline Marketing: Watermark on Electronic Receipts&quot;">​</a></h3><p>Enable <strong>&quot;Place QR code on receipts&quot;</strong>, and every digital sales receipt generated in the POS terminal will include a branded referral badge with your personal QR code. Handing or sending receipts to clients organically brings in new users.</p><hr><h2 id="📋-2-campaigns-crm-tab-publication-management" tabindex="-1">📋 2. &quot;Campaigns (CRM)&quot; Tab: Publication Management <a class="header-anchor" href="#📋-2-campaigns-crm-tab-publication-management" aria-label="Permalink to &quot;📋 2. &quot;Campaigns (CRM)&quot; Tab: Publication Management&quot;">​</a></h2><p>All created links are automatically saved in the central campaign registry, allowing you to manage your promotional pipeline:</p><ul><li><strong>Visual Statuses:</strong> Track publication progress (<code>Idea</code> ➔ <code>In Progress</code> ➔ <code>Published</code> ➔ <code>Completed</code> / <code>Rejected</code>).</li><li><strong>Deal Tracking:</strong> Record allocated budgets, contact info for bloggers or channel admins, notes, and live published URLs.</li><li><strong>1-Click AI Generation:</strong> Click the magic wand icon in any campaign row to instantly open the AI Marketer pre-configured for that campaign.</li></ul><hr><h2 id="🤖-3-ai-marketer-tab-content-creation-growth-strategy" tabindex="-1">🤖 3. &quot;AI Marketer&quot; Tab: Content Creation &amp; Growth Strategy <a class="header-anchor" href="#🤖-3-ai-marketer-tab-content-creation-growth-strategy" aria-label="Permalink to &quot;🤖 3. &quot;AI Marketer&quot; Tab: Content Creation &amp; Growth Strategy&quot;">​</a></h2><p>The built-in AI assistant helps write engaging promo copy and discovers creative marketing channels for your niche:</p><ul><li><strong>Content Formats:</strong><ul><li><em>Growth Strategy &amp; Platform Selection (AI Growth):</em> The AI analyzes your product and recommends specific channels, audience hooks, and an outreach plan.</li><li><em>Social Media Posts (VK, Telegram):</em> Catchy posts with emojis and calls to action.</li><li><em>Case Study Articles (Habr, VC.ru, Pikabu):</em> In-depth stories and experiential longreads.</li><li><em>Direct Outreach (Pitch Letters):</em> Friendly, tailored partnership proposals for bloggers and micro-influencers.</li><li><em>Email Newsletters:</em> Structured announcements for your customer base.</li></ul></li><li><strong>Deterministic Link Protection:</strong> The AI never hallucinates or distorts UTM tags; the application reliably inserts your exact tracking link into the generated text.</li><li><strong>MCP Agent Export:</strong> Click the export button to generate a standardized JSON context payload for autonomous AI agents (Cursor, Antigravity, Browser-Use).</li><li><strong>Live Discovery:</strong> Smart background fetching of available AI models from the provider&#39;s API upon entering your key (eliminates the need to manually hunt for new model IDs).</li><li><strong>Enterprise Security:</strong> API keys are encrypted at the OS level via Windows DPAPI.</li></ul><hr><h2 id="💰-4-affiliate-rewards-bonus-store" tabindex="-1">💰 4. Affiliate Rewards &amp; Bonus Store <a class="header-anchor" href="#💰-4-affiliate-rewards-bonus-store" aria-label="Permalink to &quot;💰 4. Affiliate Rewards &amp; Bonus Store&quot;">​</a></h2><p>When introducing colleagues to OmniCraft ERP, you benefit from <strong>Lifetime Attribution</strong>: you receive commissions on all subsequent subscription renewals and module purchases.</p><h3 id="commission-tiers" tabindex="-1">Commission Tiers: <a class="header-anchor" href="#commission-tiers" aria-label="Permalink to &quot;Commission Tiers:&quot;">​</a></h3><ul><li>🥉 <strong>Partner</strong> (1–3 sales/month) ➔ <strong>20%</strong> commission</li><li>🥈 <strong>Master</strong> (4–9 sales/month) ➔ <strong>30%</strong> commission</li><li>👑 <strong>Legend</strong> (10+ sales/month) ➔ <strong>50%</strong> commission</li></ul><h3 id="🎁-bonus-store-redemption" tabindex="-1">🎁 Bonus Store (Redemption): <a class="header-anchor" href="#🎁-bonus-store-redemption" aria-label="Permalink to &quot;🎁 Bonus Store (Redemption):&quot;">​</a></h3><p>Your balance is displayed on the main dashboard. Click <em>&quot;Redeem bonuses&quot;</em> to spend points on:</p><ul><li>Standard subscription renewal.</li><li>Lifetime upgrade to PRO.</li><li>Specialized marketplace modules (e.g., Pattern Module).</li></ul>',26)])])}const p=t(n,[["render",i]]);export{g as __pageData,p as default};
